 #[test]fn bullet_robot_ground_attack_becomes_source_move_with_metadata_two(){let mut g=field();g.units[0].kind="grunt".into();g.units[0].native_class7c=0;assert!(g.record_native_order_event(0,Event::classified(5,[3456,600],500)));assert_eq!(g.dispatch_native_attack_order(0),Some(Result::Move));assert_eq!(g.units[0].native_order5c,-1);assert_eq!(g.units[0].dest,Some((1184.,984.)));let slot=g.units[0].native_slot.unwrap();let p=&g.native_group_rosters.members[slot].as_ref().unwrap().promotion;assert_eq!((p.target_x,p.target_y,p.target_aux),(600,500,2));assert_eq!(g.native_group_rosters.pool[g.native_group_rosters.current_roster.unwrap()].roster[9]&8,8);}
 #[test]fn protected_target_uses_original_failed_group_goal_and_acknowledges_the_command(){let mut g=field();g.units[0].kind="grunt".into();g.units[0].native_class7c=0;let e=g.native_ui_target_order_event(1,false).unwrap();assert!(g.record_native_order_event(0,e));g.units[1].native_protectionaa=1;assert_eq!(g.dispatch_native_attack_order(0),Some(Result::Cancelled));assert_eq!(g.units[0].native_order5c,0);let group=g.native_group_rosters.current_roster.unwrap();assert_eq!(g.native_group_rosters.pool[group].roster[58],0);assert_eq!((g.native_group_rosters.pool[group].word(44),g.native_group_rosters.pool[group].word(46)),(168,168));assert_eq!(g.units[0].native_phase35,42);}
 #[test]fn attack_visibility_switches_only_on_a_real_ground_building_query(){let mut g=field();assert!(g.record_native_order_event(0,Event::classified(5,[3456,200],200)));assert_eq!(g.native_attack_visible(0),Some(true));assert!(!g.native_attack_ray_building);let mut snap=g.begin_native_attack_walk(0,1);assert!(snap.is_none());g.units[0].native_phase35=8;snap=g.begin_native_attack_walk(0,1);let phase=g.units[0].native_phase35;assert_eq!(phase,2);assert!(g.finish_native_attack_walk(0,snap.unwrap(),phase,false));assert_eq!(g.units[0].native_phase35,8);}
